  }
  /** Status text of the response, or `undefined` when unset. See {@link HTTPResponse.status}. */
  get statusText(): string | undefined {
    return this.#init?.statusText;
  }
  get headers(): Headers {
    return (this.#headers ||= new Headers(this.#init?.headers));
