1	import type { Mock } from "vitest";
2	import type { H3Config, H3Event, NodeHandler, HTTPError } from "../src/index.ts";
3	import { tracingPlugin } from "../src/tracing.ts";
4	import { Server as NodeServer } from "node:http";
5	import { getRandomPort } from "get-port-please";
6	import { beforeEach, afterEach, vi, it, describe, expect, beforeAll, afterAll } from "vitest";
7	import { H3 } from "../src/index.ts";
8	import { toNodeHandler } from "../src/_entries/node.ts";
9	
10	// Matrix
11	export function describeMatrix(
12	  title: string,
13	  fn: (ctx: TestContext, testUtils: TestUtils) => void | Promise<void>,
14	  opts?: TestOptions,
15	): void {
16	  const run = (ctx: TestContext) => {
17	    const utils: TestUtils = {
18	      expect,
19	      describe,
20	      it: Object.assign(interceptFnWithSuffix(it, ctx.target), {
21	        only: interceptFnWithSuffix(it.only, ctx.target),
22	        todo: interceptFnWithSuffix(it.todo, ctx.target),
23	        skip: interceptFnWithSuffix(it.skip, ctx.target),
24	        skipIf: (condition: boolean) => (condition ? utils.it.skip : utils.it),
25	        runIf: (condition: boolean) => (condition ? utils.it : utils.it.skip),
26	      }),
27	    };
28	    fn(ctx, utils);
29	  };
30	  describe(title, () => {
31	    describe("web", () => {
32	      run(setupWebTest(opts));
33	    });
34	    describe("node", () => {
35	      run(setupNodeTest(opts));
36	    });
37	  });
38	}
39	
40	// Web
41	function setupWebTest(opts: TestOptions = {}): TestContext {
42	  const ctx = setupBaseTest("web", opts);
43	  beforeEach(() => {
44	    ctx.fetch = (input, init) => {
45	      const headers = new Headers(init?.headers);
46	      if (input.startsWith("/") && !headers.has("host") && !headers.has("x-forwarded-host")) {
47	        headers.set("Host", "localhost");
48	      }
49	      return Promise.resolve(
50	        ctx.app.request(input, {
51	          ...init,
52	          headers,
53	        }),
54	      );
55	    };
56	  });
57	  return ctx;
58	}
59	
60	// Node.js
61	function setupNodeTest(opts: TestOptions = {}): TestContext {
62	  const ctx = setupBaseTest("node", opts);
63	
64	  let server: NodeServer;
65	  let handler: NodeHandler;
66	
67	  beforeAll(async () => {
68	    server = new NodeServer((req, res) => {
69	      handler!(req, res);
70	    });
71	    const port = await getRandomPort();
72	    await new Promise<void>((resolve) => server.listen(port, resolve));
73	    ctx.url = `http://localhost:${port}`;
74	    ctx.fetch = (input, init = {}) => {
75	      const url = new URL(input, ctx.url);
76	      const headers = new Headers(init.headers);
77	      // Emulate a reverse proxy
78	      if (!headers.has("host")) {
79	        headers.set("Host", url.host);
80	      }
81	      if (!headers.has("x-forwarded-host")) {
82	        headers.set("X-Forwarded-Host", url.host);
83	      }
84	      if (url.protocol === "https:" && !headers.has("x-forwarded-proto")) {
85	        headers.set("X-Forwarded-Proto", "https");
86	      }
87	      return fetch(`${ctx.url}${url.pathname}${url.search}`, {
88	        redirect: "manual",
89	        // @ts-expect-error undici/node specific
90	        duplex: "half",
91	        ...init,
92	        headers,
93	      });
94	    };
95	  });
96	
97	  afterAll(async () => {
98	    server.closeAllConnections();
99	    await new Promise<void>((resolve, reject) =>
100	      server.close((err) => (err ? reject(err) : resolve())),
101	    );
102	    server = undefined!;
103	  });
104	
105	  beforeEach(async () => {
106	    handler = toNodeHandler(ctx.app);
107	  });
108	
109	  afterEach(() => {
110	    handler = undefined!;
111	  });
112	
113	  return ctx;
114	}
115	
116	// Base
117	function setupBaseTest(target: TestContext["target"], opts: TestOptions = {}): TestContext {
118	  const ctx: TestContext = { target } as TestContext;
119	
120	  beforeEach(async () => {
121	    ctx.hooks = {
122	      onRequest: vi.fn(),
123	      onError: vi.fn(),
124	      onResponse: vi.fn(),
125	    };
126	
127	    ctx.errors = [];
128	    ctx.hooks.onError.mockImplementation((error, _event: H3Event) => {
129	      if (opts.debug) {
130	        console.error(error);
131	      }
132	      ctx.errors.push(error);
